import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import type React from 'react';
import { useState } from 'react';
import { templatesApi } from '@/api/templates';
import { useNotification } from '@/components/notification';
import { useTemplatesStore } from '@/store/templates';
import type { Template } from '@/types/templates';
import { TemplateTypeSelector } from './template-type-selector';

// Top-level regex for performance (lint compliance)
const ADMIN_AJAX_SUFFIX_RE = /admin-ajax\.php$/;

// 获取模板的大类显示标签
const getTemplateCategoryLabel = (
  template: Template,
  templateTypesData: any
) => {
  // 从 templateTypesData 中找到匹配的类型
  const matchingType = templateTypesData?.types?.find(
    (t: any) =>
      t.simple_type === template.type ||
      (typeof t.value === 'string' && t.value.includes(template.type))
  );

  if (matchingType) {
    // 直接返回组名
    return matchingType.group;
  }

  // 备用逻辑 - 根据类型判断大类
  if (['404', 'search', 'home', 'blog', 'author'].includes(template.type)) {
    return '核心模板';
  }
  if (['header', 'footer'].includes(template.type)) {
    return '布局部件';
  }
  if (template.type === 'single') {
    return '单页';
  }
  if (template.type === 'archive') {
    return '列表页';
  }
  if (
    template.type === 'category' ||
    template.type === 'tag' ||
    (template.type as string) === 'taxonomy'
  ) {
    return '分类法';
  }

  return '其他';
};

export const TemplatesList: React.FC = () => {
  const { notify } = useNotification();
  const queryClient = useQueryClient();
  const [showTypeSelector, setShowTypeSelector] = useState(false);

  const { templates, filter, setTemplates, setFilter, removeTemplate } =
    useTemplatesStore();

  // 获取可用的模板类型
  const { data: templateTypesData } = useQuery({
    queryKey: ['template-types'],
    queryFn: templatesApi.getTypes,
  });

  // 获取模板列表
  const { isLoading } = useQuery({
    queryKey: ['templates'],
    queryFn: async () => {
      const response = await templatesApi.list();
      setTemplates(response.templates);
      return response;
    },
  });

  // 删除模板
  const deleteMutation = useMutation({
    mutationFn: templatesApi.delete,
    onSuccess: (_, templateId) => {
      notify('success', '模板已删除');
      removeTemplate(templateId);
      queryClient.invalidateQueries({ queryKey: ['templates'] });
    },
    onError: () => {
      notify('error', '删除失败，请重试');
    },
  });

  // 简化的过滤选项 - 按大类过滤
  const filterOptions = [
    { value: 'all', label: '全部模板' },
    { value: 'core', label: '核心模板' },
    { value: 'parts', label: '布局部件' },
    { value: 'single', label: '单页' },
    { value: 'archive', label: '列表页' },
    { value: 'taxonomy', label: '分类法' },
  ];

  // 根据大类过滤模板
  const filteredTemplates = templates.filter((template) => {
    // 搜索过滤
    if (
      filter.search &&
      !template.title.toLowerCase().includes(filter.search.toLowerCase())
    ) {
      return false;
    }

    // 类型过滤
    if (filter.type === 'all') {
      return true;
    }

    // 从 templateTypesData 中查找模板的组信息
    const matchingType = templateTypesData?.types.find(
      (t) =>
        t.simple_type === template.type ||
        (typeof t.value === 'string' && t.value.includes(template.type))
    );

    if (!matchingType) {
      return false;
    }

    // 根据过滤器类型进行匹配
    switch (filter.type) {
      case 'core':
        return matchingType.group === '核心模板';
      case 'parts':
        return matchingType.group === '布局部件';
      case 'single':
        return matchingType.value.startsWith('single_');
      case 'archive':
        return matchingType.value.startsWith('archive_');
      case 'taxonomy':
        return (
          matchingType.group === '分类法' ||
          matchingType.value.startsWith('taxonomy_')
        );
      default:
        return false;
    }
  });

  const handleDelete = (template: Template) => {
    if (window.confirm(`确定要删除模板"${template.title}"吗？`)) {
      deleteMutation.mutate(template.id);
    }
  };

  const buildTemplateEditorUrl = (templateId: number | string) => {
    const ajaxUrl =
      (typeof (window as any).ajaxurl === 'string' &&
        (window as any).ajaxurl) ||
      window.zeroySettings?.ajaxUrl ||
      window.location.href;

    const url = new URL(ajaxUrl, window.location.href);

    if (!url.pathname.endsWith('admin.php')) {
      if (url.pathname.endsWith('admin-ajax.php')) {
        url.pathname = url.pathname.replace(ADMIN_AJAX_SUFFIX_RE, 'admin.php');
      } else {
        const segments = url.pathname.split('/');
        segments[segments.length - 1] = 'admin.php';
        url.pathname = segments.join('/');
      }
    }

    url.search = '';
    url.searchParams.set('page', 'zeroy-template-editor');
    url.searchParams.set('template_id', String(templateId));

    return url.toString();
  };

  const handleEdit = (template: Template) => {
    // 重定向到 zeroy 编辑器
    const editUrl = buildTemplateEditorUrl(template.id);
    window.location.href = editUrl;
  };

  const handleCreate = () => {
    setShowTypeSelector(true);
  };

  const handleTypeSelected = async (fullType: string, simpleType: string) => {
    try {
      // 创建一个空模板
      const response = await templatesApi.create({
        content: '',
        type: simpleType as any,
        full_type: fullType,
      });

      // 创建成功后直接跳转到编辑器
      const editUrl = buildTemplateEditorUrl(response.template.id);
      window.location.href = editUrl;
    } catch (error: any) {
      notify('error', error.response?.data?.message || '创建模板失败，请重试');
    }
  };

  const handlePreview = async (template: Template) => {
    try {
      const response = await templatesApi.getPreviewUrl(template.id);

      if (!response.url) {
        notify('error', '无法预览此模板');
        return;
      }

      window.open(response.url, '_blank');
    } catch {
      notify('error', '获取预览链接失败');
    }
  };

  if (isLoading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <div className="text-gray-500">加载中...</div>
      </div>
    );
  }

  return (
    <div>
      {/* 工具栏 */}
      <div className="mb-6 flex items-center justify-between">
        <div className="flex items-center space-x-4">
          {/* 类型筛选 */}
          <select
            className="rounded-md border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
            onChange={(e) => setFilter({ type: e.target.value as any })}
            value={filter.type}
          >
            {filterOptions.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>

          {/* 搜索框 */}
          <input
            className="rounded-md border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
            onChange={(e) => setFilter({ search: e.target.value })}
            placeholder="搜索模板..."
            type="text"
            value={filter.search}
          />
        </div>

        {/* 创建按钮 */}
        <button
          className="rounded-md bg-blue-600 px-4 py-2 font-medium text-sm text-white hover:bg-blue-700"
          onClick={handleCreate}
          type="button"
        >
          创建模板
        </button>
      </div>

      {/* 模板列表 */}
      <div className="rounded-lg border border-gray-200 bg-white">
        {filteredTemplates.length === 0 ? (
          <div className="p-8 text-center text-gray-500">暂无模板</div>
        ) : (
          <table className="w-full">
            <thead>
              <tr className="border-gray-200 border-b bg-gray-50">
                <th className="px-6 py-3 text-left font-medium text-gray-500 text-xs uppercase tracking-wider">
                  标题
                </th>
                <th className="px-6 py-3 text-left font-medium text-gray-500 text-xs uppercase tracking-wider">
                  类型
                </th>
                <th className="px-6 py-3 text-right font-medium text-gray-500 text-xs uppercase tracking-wider">
                  操作
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {filteredTemplates.map((template) => (
                <tr className="hover:bg-gray-50" key={template.id}>
                  <td className="whitespace-nowrap px-6 py-4 font-medium text-gray-900 text-sm">
                    {template.title}
                  </td>
                  <td className="whitespace-nowrap px-6 py-4 text-gray-500 text-sm">
                    {getTemplateCategoryLabel(template, templateTypesData)}
                  </td>
                  <td className="whitespace-nowrap px-6 py-4 text-right font-medium text-sm">
                    <button
                      className="mr-3 text-blue-600 hover:text-blue-900"
                      onClick={() => handleEdit(template)}
                      type="button"
                    >
                      编辑
                    </button>
                    <button
                      className="mr-3 text-gray-600 hover:text-gray-900"
                      onClick={() => handlePreview(template)}
                      type="button"
                    >
                      预览
                    </button>
                    <button
                      className="text-red-600 hover:text-red-900"
                      onClick={() => handleDelete(template)}
                      type="button"
                    >
                      删除
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* 模板类型选择器 */}
      <TemplateTypeSelector
        isOpen={showTypeSelector}
        onClose={() => setShowTypeSelector(false)}
        onSelect={handleTypeSelected}
      />
    </div>
  );
};
