import { useQuery } from '@tanstack/react-query';
import type React from 'react';
import { useState } from 'react';
import { templatesApi } from '@/api/templates';
import { useNotification } from '@/components/notification';

interface TemplateTypeSelectorProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (fullType: string, simpleType: string) => void;
}

export const TemplateTypeSelector: React.FC<TemplateTypeSelectorProps> = ({
  isOpen,
  onClose,
  onSelect,
}) => {
  const { notify } = useNotification();
  const [selectedType, setSelectedType] = useState('');

  // Get available template types
  const { data: typesData, isLoading } = useQuery({
    queryKey: ['template-types'],
    queryFn: templatesApi.getTypes,
    enabled: isOpen,
  });

  if (!isOpen) {
    return null;
  }

  const handleConfirm = () => {
    if (!selectedType) {
      notify('error', '请选择模板类型');
      return;
    }

    // Extract simple type from full type
    let simpleType = selectedType;
    if (selectedType.startsWith('single_')) {
      simpleType = 'single';
    } else if (selectedType.startsWith('archive_')) {
      simpleType = 'archive';
    } else if (selectedType.startsWith('taxonomy_')) {
      simpleType = 'taxonomy';
    } else if (
      ['404', 'search', 'home', 'blog', 'author'].includes(selectedType)
    ) {
      simpleType = selectedType;
    }

    onSelect(selectedType, simpleType);
    setSelectedType('');
    onClose();
  };

  const handleCancel = () => {
    setSelectedType('');
    onClose();
  };

  // Get available types (not already created)
  const availableTypes = typesData?.types.filter((type) => !type.exists) || [];
  const groupedTypes = availableTypes.reduce(
    (acc, type) => {
      if (!acc[type.group]) {
        acc[type.group] = [];
      }
      acc[type.group].push(type);
      return acc;
    },
    {} as Record<string, typeof availableTypes>
  );

  return (
    <div className="fixed inset-0 z-9990 flex items-center justify-center bg-black bg-opacity-50">
      <div className="w-full max-w-md overflow-hidden rounded-lg bg-white shadow-xl">
        <div className="border-gray-200 border-b px-6 py-4">
          <h2 className="font-semibold text-gray-900 text-xl">选择模板类型</h2>
        </div>

        <div className="px-6 py-4">
          {isLoading && (
            <div className="text-center text-gray-500 text-sm">加载中...</div>
          )}

          {!isLoading && availableTypes.length === 0 && (
            <div className="text-center text-red-600 text-sm">
              所有模板类型都已创建
            </div>
          )}

          {!isLoading && availableTypes.length > 0 && (
            <div>
              <label
                className="mb-2 block text-gray-700 text-sm"
                htmlFor="template-type-select"
              >
                请选择要创建的模板类型：
              </label>
              <select
                className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
                id="template-type-select"
                onChange={(e) => setSelectedType(e.target.value)}
                value={selectedType}
              >
                <option value="">请选择模板类型</option>
                {Object.entries(groupedTypes).map(([groupName, types]) => (
                  <optgroup key={groupName} label={groupName}>
                    {types.map((type) => (
                      <option key={type.value} value={type.value}>
                        {type.label}
                      </option>
                    ))}
                  </optgroup>
                ))}
              </select>
            </div>
          )}
        </div>

        <div className="flex items-center justify-end border-gray-200 border-t px-6 py-4">
          <button
            className="mr-3 px-4 py-2 font-medium text-gray-700 text-sm hover:text-gray-800"
            onClick={handleCancel}
            type="button"
          >
            取消
          </button>
          <button
            className="rounded-md bg-blue-600 px-4 py-2 font-medium text-sm text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
            disabled={!selectedType || availableTypes.length === 0}
            onClick={handleConfirm}
            type="button"
          >
            下一步
          </button>
        </div>
      </div>
    </div>
  );
};
