import { create } from 'zustand';
import type { Template } from '@/types/templates';

interface TemplatesState {
  templates: Template[];
  selectedTemplate: Template | null;
  isLoading: boolean;
  filter: {
    type: string; // Changed to support custom filter values like 'core', 'parts', etc.
    search: string;
  };
  setTemplates: (templates: Template[]) => void;
  setSelectedTemplate: (template: Template | null) => void;
  setLoading: (loading: boolean) => void;
  setFilter: (filter: Partial<TemplatesState['filter']>) => void;
  addTemplate: (template: Template) => void;
  updateTemplate: (id: number, updates: Partial<Template>) => void;
  removeTemplate: (id: number) => void;
}

export const useTemplatesStore = create<TemplatesState>((set) => ({
  templates: [],
  selectedTemplate: null,
  isLoading: false,
  filter: {
    type: 'all',
    search: '',
  },

  setTemplates: (templates) => set({ templates }),

  setSelectedTemplate: (template) => set({ selectedTemplate: template }),

  setLoading: (loading) => set({ isLoading: loading }),

  setFilter: (filter) =>
    set((state) => ({
      filter: { ...state.filter, ...filter },
    })),

  addTemplate: (template) =>
    set((state) => ({
      templates: [...state.templates, template],
    })),

  updateTemplate: (id, updates) =>
    set((state) => ({
      templates: state.templates.map((t) =>
        t.id === id ? { ...t, ...updates } : t
      ),
      selectedTemplate:
        state.selectedTemplate?.id === id
          ? { ...state.selectedTemplate, ...updates }
          : state.selectedTemplate,
    })),

  removeTemplate: (id) =>
    set((state) => ({
      templates: state.templates.filter((t) => t.id !== id),
      selectedTemplate:
        state.selectedTemplate?.id === id ? null : state.selectedTemplate,
    })),
}));
