import type {
  CreateTemplateData,
  TemplateListResponse,
  TemplateResponse,
  UpdateTemplateData,
} from '@/types/templates';
import { apiClient } from './client';

export const templatesApi = {
  /**
   * 获取模板列表
   */
  list(): Promise<TemplateListResponse> {
    return apiClient.get('/templates');
  },

  /**
   * 获取可用的模板类型
   */
  getTypes(): Promise<{
    types: Array<{
      value: string;
      label: string;
      group: string;
      exists: boolean;
      simple_type: string;
    }>;
    existing: string[];
  }> {
    return apiClient.get('/templates/types');
  },

  /**
   * 获取单个模板
   */
  get(id: number): Promise<TemplateResponse> {
    return apiClient.get(`/templates/${id}`);
  },

  /**
   * 创建模板
   */
  create(data: CreateTemplateData): Promise<TemplateResponse> {
    return apiClient.post('/templates', data);
  },

  /**
   * 更新模板
   */
  update(data: UpdateTemplateData): Promise<TemplateResponse> {
    const { id, ...updateData } = data;
    return apiClient.put(`/templates/${id}`, updateData);
  },

  /**
   * 删除模板
   */
  delete(id: number): Promise<{ message: string }> {
    return apiClient.delete(`/templates/${id}`);
  },

  /**
   * 获取预览URL
   */
  getPreviewUrl(
    id: number
  ): Promise<{ url: string; available?: boolean; message?: string }> {
    return apiClient.get(`/templates/${id}/preview-url`);
  },
};
